// Runs every XCTestCase subclass in the linked test sources without XCTest.
//
// Swift has no runtime class enumeration on Linux, and none is needed on macOS
// either: the test classes are listed explicitly below. When a new test class is
// added, add it here too — `Scripts/check-test-registry.sh` fails if one is missing.

import Foundation

// `Tools/TestRunner/Tests` is generated by Scripts/test-without-xcode.sh (and by CI)
// from the real test sources; the suite list below names every class in those files.
let suites: [(name: String, cases: [XCTestCase])] = [
    ("StoreTests", [StoreTests()]),
    ("StoreRuntimeSettingsTests", [StoreRuntimeSettingsTests()]),
    ("TodayMetricsTests", [TodayMetricsTests()]),
    ("OllamaModelPolicyTests", [OllamaModelPolicyTests()]),
    ("OllamaTagsParserTests", [OllamaTagsParserTests()]),
    ("JSONResponseExtractorTests", [JSONResponseExtractorTests()]),
    ("HourlyAggregateTests", [HourlyAggregateTests()]),
    ("PrivacyGateTests", [PrivacyGateTests()]),
    ("CapturePrivacyTests", [CapturePrivacyTests()]),
    ("LiveStatePrivacyTests", [LiveStatePrivacyTests()]),
    ("AttributionBufferTests", [AttributionBufferTests()]),
    ("AttributionPersistenceTests", [AttributionPersistenceTests()]),
    ("TriggerAccountingIntegrationTests", [TriggerAccountingIntegrationTests()]),
    ("RecommendationEngineTests", [RecommendationEngineTests()]),
    ("ConflictResolverTests", [ConflictResolverTests()]),
    ("LearnCandidateTests", [LearnCandidateTests()]),
    ("ShortcutActionManagerTests", [ShortcutActionManagerTests()]),
    ("KeyComboTests", [KeyComboTests()]),
    ("ApplyAtomicityTests", [ApplyAtomicityTests()]),
    ("WorkspaceActionTests", [WorkspaceActionTests()]),
    ("MenuCommandPatternTests", [MenuCommandPatternTests()]),
    ("WorkspacePatternTests", [WorkspacePatternTests()]),
    ("T1StorageTests", [T1StorageTests()]),
    ("WeeklyReviewTests", [WeeklyReviewTests()]),
    ("DateBucketsTests", [DateBucketsTests()]),
    ("OptionalAITests", [OptionalAITests()]),
    ("AISafetyGapTests", [AISafetyGapTests()]),
    ("SystemUICaptureTests", [SystemUICaptureTests()]),
    ("CodeToolCaptureTests", [CodeToolCaptureTests()]),
    ("ExclusionListConsistencyTests", [ExclusionListConsistencyTests()]),
    ("EndpointNormalisationTests", [EndpointNormalisationTests()]),
    ("AXMenuCodecTests", [AXMenuCodecTests()]),
    ("AppleModifierConversionTests", [AppleModifierConversionTests()]),
]

/// Every `func test…()` on an instance, discovered by reflection.
func testMethods(of object: XCTestCase) -> [String] {
    var names: [String] = []
    // Swift's Mirror cannot enumerate methods; the Objective-C runtime can, because
    // `XCTestCase` is `NSObject` + `@objcMembers`.
    var count: UInt32 = 0
    if let methods = class_copyMethodList(type(of: object), &count) {
        for index in 0..<Int(count) {
            let selector = String(describing: method_getName(methods[index]))
            if selector.hasPrefix("test") {
                names.append(selector)
            }
        }
        free(methods)
    }
    return names.sorted()
}

print("ShortcutSense test run (XCTest-compatible shim)")
print("Platform: \(ProcessInfo.processInfo.operatingSystemVersionString)")
print("")

let started = Date()
var total = 0
var failures = 0

for suite in suites {
    print(suite.name)
    for object in suite.cases {
        // Class-level methods: each test is a selector on the shared instance.
        let methods = testMethods(of: object)
        guard !methods.isEmpty else {
            print("  (no tests discovered)")
            continue
        }
        for selector in methods {
            let testName = "\(suite.name).\(selector.replacingOccurrences(of: "test", with: "", options: .anchored))"
            TestReporter.shared.begin(testName)
            do {
                try object.setUpWithError()
                let imp = object.method(for: NSSelectorFromString(selector))
                typealias Function = @convention(c) (AnyObject, Selector) -> Void
                let function = unsafeBitCast(imp, to: Function.self)
                function(object, NSSelectorFromString(selector))
                try object.tearDownWithError()
            } catch let skip as XCTSkip {
                print("  - \(testName) skipped: \(skip.message)")
                _ = TestReporter.shared.end()
                total += 1
                continue
            } catch {
                TestReporter.shared.recordFailure("threw \(error)", file: #filePath, line: #line)
            }
            let passed = TestReporter.shared.end()
            total += 1
            if !passed { failures += 1 }
        }
    }
    print("")
}

let elapsed = Date().timeIntervalSince(started)
print(String(format: "Executed %d tests, with %d failures in %.2f seconds",
             total, failures, elapsed))
exit(failures == 0 ? 0 : 1)
